MessageConsumer consumer = session.createConsumer(queue);
consumer.setMessageListener(message -> {
    try {
        handle(message.getBody(String.class));   // provider-invoked
        session.commit();                        // transacted session
    } catch (Exception e) {
        rollbackAndDeadLetter(session, e);       // never let it escape onMessage
    }
});
// no receive() call: the provider's delivery thread invokes us

